class Solution {
public:
    int minOperations(vector<int>& nums) {
        // Dilworth's theorem: min strictly increasing chains = longest non-increasing antichain
        vector<int> tails;
        for (int i = (int)nums.size() - 1; i >= 0; --i) {
            int x = nums[i];
            auto it = upper_bound(tails.begin(), tails.end(), x);
            if (it == tails.end()) {
                tails.push_back(x);
            } else {
                *it = x;
            }
        }
        return tails.size();
    }
};

class Solution {
    public int minOperations(int[] nums) {
        List<Integer> tails = new ArrayList<>();
        for (int i = nums.length - 1; i >= 0; --i) {
            int x = nums[i];
            int l = 0, r = tails.size();
            while (l < r) {
                int mid = (l + r) / 2;
                if (tails.get(mid) <= x) {
                    l = mid + 1;
                } else {
                    r = mid;
                }
            }
            if (l == tails.size()) {
                tails.add(x);
            } else {
                tails.set(l, x);
            }
        }
        return tails.size();
    }
}

var minOperations = function(nums) {
    const tails = [];
    for (let i = nums.length - 1; i >= 0; i--) {
        const x = nums[i];
        let l = 0, r = tails.length;
        while (l < r) {
            const mid = Math.floor((l + r) / 2);
            if (tails[mid] <= x) {
                l = mid + 1;
            } else {
                r = mid;
            }
        }
        if (l === tails.length) {
            tails.push(x);
        } else {
            tails[l] = x;
        }
    }
    return tails.length;
};
